//! Stable library entry points for the codegen pipeline.
//!
//! The thin `codegraph` binary delegates to these functions, and consumer
//! wrapper binaries (generated by `codegraph init` as `{name}-graph`) call
//! them directly instead of forking the generate modules.

use std::collections::HashSet;
use std::path::{Path, PathBuf};

use codegraph_backend::{create_backend, BackendConfig};

use crate::error::Result;
use crate::generate::ProjectConfig;

/// Output format for the `classify` command.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ClassifyFormat {
    Table,
    Json,
}

/// Arguments for the full pipeline (`run`): ingest the model sources
/// (mox-first, then JSON schemas), classify, then run all generators.
pub struct RunArgs<'a> {
    /// JSON schema directory. Optional when `mox_files` is provided
    /// (mox-first, issue #231); schemas-only runs are deprecated as the
    /// primary model source but keep identical behavior.
    pub schemas: Option<&'a Path>,
    /// classifier.toml path. Required when `schemas` is provided; ignored
    /// (an empty config is used) for mox-only runs without one.
    pub classifier: Option<&'a Path>,
    pub config_path: &'a Path,
    pub output: &'a Path,
    pub extension_points_path: Option<&'a Path>,
    pub profile_name: &'a str,
    pub variant: Option<&'a str>,
    pub profiles_config_path: Option<PathBuf>,
    pub no_post_gen: bool,
    pub template_dir: &'a [PathBuf],
    pub ifml_files: &'a [PathBuf],
    pub openapi_files: &'a [PathBuf],
    /// rexlang `.mox` domain model files to compile in-process and ingest
    /// into the graph (vocabularies with facets, class operations, derived
    /// features). Absent/empty = no mox ingest, generators unchanged.
    pub mox_files: &'a [PathBuf],
    /// Rosetta (Rune DSL) `.rosetta` model files, bridged into the graph
    /// data plane (issue #256). Ingested after mox and BEFORE the JSON
    /// schema pass; bridged titles join the schema pass's skip-set.
    pub rosetta_files: &'a [PathBuf],
    pub ifml_framework: &'a [String],
    /// Optional `ifml-components.toml` mapping IFML components to
    /// handcrafted framework components. Absent = all built-in templates.
    pub ifml_components: Option<&'a Path>,
    /// Built-in IFML design-system pack name (e.g. "shadcn-svelte").
    /// Overrides the profiles.toml `ifml_design_system` feature. Project
    /// `ifml_components` entries take precedence over pack entries.
    pub ifml_design_system: Option<&'a str>,
    /// Git rev to pin in generated Cargo.toml codegraph deps. When None the
    /// driver falls back to `git rev-parse HEAD` of the current directory.
    pub codegraph_rev: Option<String>,
}

/// Arguments for the IFML-only UI generation path (`ifml_generate`).
pub struct IfmlGenerateArgs<'a> {
    pub config_path: &'a Path,
    pub output: &'a Path,
    pub ifml_files: &'a [PathBuf],
    /// Optional JSON schema directory — enables entity resolution enrichment.
    pub schemas: Option<&'a Path>,
    /// Path to classifier.toml (required only with `schemas`).
    pub classifier: Option<&'a Path>,
    /// IFML framework targets (e.g. "svelte", "react"). Empty defaults to svelte.
    pub frameworks: &'a [String],
    /// Optional path to profiles.toml.
    pub profiles_config_path: Option<PathBuf>,
    pub template_dir: &'a [PathBuf],
    /// Optional `ifml-components.toml` mapping IFML components to
    /// handcrafted framework components. Absent = all built-in templates.
    pub ifml_components: Option<&'a Path>,
    /// Built-in IFML design-system pack name (e.g. "shadcn-svelte").
    /// Overrides the profiles.toml `ifml_design_system` feature. Project
    /// `ifml_components` entries take precedence over pack entries.
    pub ifml_design_system: Option<&'a str>,
}

fn load_ifml_component_mappings(
    path: Option<&Path>,
    design_system: Option<&str>,
) -> Result<Option<codegraph_config::IfmlComponentMappings>> {
    let project = match path {
        Some(path) => codegraph_config::IfmlComponentMappings::load(path)
            .map(Some)
            .map_err(crate::error::Error::Config)?,
        None => None,
    };
    let pack = match design_system.filter(|name| !name.is_empty()) {
        Some(name) => {
            Some(codegraph_config::built_in_pack(name).map_err(crate::error::Error::Config)?)
        }
        None => None,
    };
    Ok(match (project, pack) {
        (Some(project), Some(pack)) => Some(
            codegraph_config::IfmlComponentMappings::merge_with_pack(project, &pack),
        ),
        (Some(project), None) => Some(project),
        (None, Some(pack)) => Some(pack),
        (None, None) => None,
    })
}

/// Effective design-system pack: the explicit argument wins over the
/// profile's `ifml_design_system` feature; empty values mean "no pack".
fn effective_design_system<'a>(
    arg: Option<&'a str>,
    build_plan: Option<&'a crate::profile::BuildPlan>,
) -> Option<&'a str> {
    arg.filter(|name| !name.is_empty()).or_else(|| {
        build_plan
            .and_then(|bp| bp.features.get("ifml_design_system"))
            .and_then(|v| v.as_str())
            .filter(|name| !name.is_empty())
    })
}

/// Stderr notice when `--schemas` is the only model source (issue #231).
pub fn schemas_deprecation_notice() -> &'static str {
    "WARN: --schemas is deprecated as the primary model source. Migrate to .mox files: codegraph migrate --schemas <dir> --output <dir>"
}

/// Stderr notice when both model sources are provided (issue #231).
pub fn mox_primary_notice() -> &'static str {
    "INFO: .mox files are the primary model source; --schemas fills gaps for types not authored in .mox"
}

/// Stderr notice when .rosetta is a provided primary source (issue #257).
pub fn rosetta_primary_notice() -> &'static str {
    "INFO: .rosetta files are a primary model source; --schemas fills gaps for types not authored in .rosetta"
}

/// Run the full pipeline: ingest + classify + generate.
pub async fn run(args: RunArgs<'_>) -> Result<()> {
    let RunArgs {
        schemas,
        classifier,
        config_path,
        output,
        extension_points_path,
        profile_name,
        variant,
        profiles_config_path,
        no_post_gen,
        template_dir,
        ifml_files,
        openapi_files,
        mox_files,
        rosetta_files,
        ifml_framework,
        ifml_components,
        ifml_design_system,
        codegraph_rev,
    } = args;

    // Model-source guard: at least one of schemas / mox files / rosetta
    // files is required, and schemas need a classifier config.
    if schemas.is_none() && mox_files.is_empty() && rosetta_files.is_empty() {
        return Err(crate::error::Error::Config(
            "no model source: provide --mox-files or --rosetta-files (primary) or --schemas"
                .to_string(),
        ));
    }
    if schemas.is_some() && classifier.is_none() {
        return Err(crate::error::Error::Config(
            "--classifier is required when --schemas is provided".to_string(),
        ));
    }

    // Notices (stderr; stdout stays clean for machine output).
    if schemas.is_some() {
        if !mox_files.is_empty() {
            eprintln!("{}", mox_primary_notice());
        } else if !rosetta_files.is_empty() {
            eprintln!("{}", rosetta_primary_notice());
        } else {
            eprintln!("{}", schemas_deprecation_notice());
        }
    }

    let backend_config = BackendConfig::default();
    let be = create_backend(&backend_config)
        .await
        .map_err(|e| crate::error::Error::Config(e.to_string()))?;

    let domain_config = codegraph_config::config::parse_domain_config(config_path)
        .map_err(|e| crate::error::Error::Config(e.to_string()))?;
    let classifier_config = match classifier {
        Some(classifier) => codegraph_classifier::config::parse_classifier_config(classifier)
            .map_err(|e| crate::error::Error::Config(e.to_string()))?,
        // An empty TOML document deserializes to the all-defaults config.
        None => codegraph_classifier::config::parse_classifier_config_str("")
            .map_err(|e| crate::error::Error::Config(e.to_string()))?,
    };

    let ui_overrides = load_ui_overrides(config_path)?;
    let ui_domains = load_ui_domains(config_path)?;

    // Load and resolve the profile.
    let profiles_path = profiles_config_path.unwrap_or_else(|| PathBuf::from("profiles.toml"));
    let registry = crate::profile::CapabilityRegistry::new();
    let mut project_config: Option<ProjectConfig> = None;
    let mut domain_types_base_path: Option<PathBuf> = None;
    let build_plan = if profiles_path.exists() || profile_name != "default" {
        let resolved =
            crate::profile::load_and_resolve_profile(&profiles_path, profile_name, variant)?;
        let plan = crate::profile::BuildPlan::from_profile(&resolved, &registry)?;

        // Build project config from profile meta (optional fields override defaults).
        let meta = &resolved.meta;
        domain_types_base_path = meta.domain_types_base.as_ref().map(|p| output.join(p));
        let database_target_str = plan.database_target().to_string();
        let persistence_provider_str = plan.persistence_provider().to_string();
        let deployment_topology_str = plan.deployment_topology().to_string();
        project_config = Some(ProjectConfig {
            app_name: meta.app_name.clone().unwrap_or_else(|| "app".into()),
            lib_name: "cosmos".into(),
            domain_types_crate: meta
                .domain_types_crate
                .clone()
                .unwrap_or_else(|| "domain_types".into()),
            hooks_api_crate: meta.hooks_api_crate.clone().unwrap_or_default(),
            api_title: meta
                .api_title
                .clone()
                .unwrap_or_else(|| "HR Open API".into()),
            generator_name: meta
                .generator_name
                .clone()
                .unwrap_or_else(|| "codegraph".into()),
            domain_types_base: meta.domain_types_base.clone().unwrap_or_default(),
            hooks_api_base: meta.hooks_api_base.clone().unwrap_or_default(),
            extensions_base: meta.extensions_base.clone().unwrap_or_default(),
            app_config_base: meta.app_config_base.clone().unwrap_or_default(),
            decision_engine_base: meta.decision_engine_base.clone().unwrap_or_default(),
            codegraph_workflow_base: meta.codegraph_workflow_base.clone().unwrap_or_default(),
            type_contracts_base: meta.type_contracts_base.clone().unwrap_or_default(),
            database_target: database_target_str,
            persistence_provider: persistence_provider_str,
            dto_key_casing: plan.dto_key_casing.clone(),
            deployment_topology: deployment_topology_str,
            types_import_prefix: domain_config.defaults.types_import_prefix.clone(),
            codegraph_rev: codegraph_rev.unwrap_or_else(current_git_rev),
            has_atproto: plan.has_atproto,
            has_fern: plan.has_fern,
            fern_sdk_languages: plan.fern_sdk_languages.clone(),
            has_emdash: plan.has_emdash,
            has_function_postconditions: resolved
                .features
                .get("function_postconditions")
                .and_then(|v| v.as_bool())
                .unwrap_or(false),
            emdash_site_pages_base: String::new(),
            emdash_site_e2e_base: String::new(),
            atproto_authority: String::new(),
            atproto_tenancy: plan.atproto_tenancy.clone(),
            atproto_float_policy: resolved
                .features
                .get("atproto_float_policy")
                .and_then(|v| v.as_str())
                .unwrap_or("integer_scaled")
                .to_string(),
            cargo_patch: String::new(),
            extra_dependencies: String::new(),
            cargo_workspace: false,
            api_version: domain_config.defaults.api_version.clone(),
        });

        println!(
            "Using profile \"{}\" (variant: {:?}) — {} entity, {} domain, {} global generators",
            resolved.meta.name,
            variant,
            plan.entity_generators.len(),
            plan.domain_generators.len(),
            plan.global_generators.len(),
        );
        Some(plan)
    } else {
        // profiles.toml doesn't exist and profile is "default" —
        // backward compat: run all generators without a plan.
        eprintln!(
            "Warning: profiles.toml not found at {} — running all generators (no profile filtering)",
            profiles_path.display()
        );
        None
    };

    // Pass 1: Ingest rexlang .mox domain sources FIRST (mox-first, issue
    // #231): vocabularies with facets, class operations, derived features,
    // and schema/property nodes for mox-authored classes and enums. The
    // bridged class titles win schema-title conflicts because the schema
    // pass below skips every title created here. Diagnostics warn and never
    // fail the run — except missing/invalid `import schema` targets, which
    // are a hard error (issue #230): the lowered model's structural
    // references depend on them.
    let mut mox_covered: HashSet<String> = HashSet::new();
    let mut mox_stats = crate::ingest::mox_ingest::MoxIngestStats::default();
    let mut pending_alias_refs: Vec<crate::ingest::mox_ingest::PendingAliasRef> = Vec::new();
    if !mox_files.is_empty() {
        println!("Pass 1: {} mox files to ingest", mox_files.len());
        let outcome = crate::ingest::mox_ingest::ingest_mox_files(
            be.ingestor(),
            be.querier(),
            mox_files,
            &domain_config,
            &domain_config.defaults.type_suffix,
        )
        .await?;
        println!("Pass 1 complete: {}", outcome.stats);
        mox_covered.extend(outcome.stats.bridged_titles.iter().cloned());
        mox_stats = outcome.stats;
        pending_alias_refs = outcome.pending_alias_refs;

        // Pass 1 (imports): the .mox model's imported JSON schema files go
        // through the same pipeline as --schemas, BEFORE the schema pass so
        // their titles join the skip-set and a file passed both ways
        // ingests exactly once (issue #230).
        if !outcome.imported_files.is_empty() {
            let imported = crate::ingest::async_ingest::ingest_imported_schemas(
                be.ingestor(),
                &outcome.imported_files,
                &classifier_config,
                &ui_overrides,
                &domain_config.defaults.type_suffix,
            )
            .await?;
            println!(
                "Pass 1 imports: {} schema files ingested",
                imported.ingested.schemas_created
            );
            mox_covered.extend(imported.titles);
        }
    }

    // Pass 1b: Rosetta (Rune DSL) data-plane bridge (issues #256, #257).
    // Runs alongside mox and BEFORE the JSON schema pass: bridged titles
    // join the skip-set so a same-titled JSON schema never duplicates the
    // node. Mox keeps primary position (rosetta wins over JSON by passing
    // first; mox wins over rosetta).
    if !rosetta_files.is_empty() {
        println!("Pass 1b: {} rosetta files to ingest", rosetta_files.len());
        let outcome = crate::ingest::rosetta_ingest::ingest_rosetta_files(
            be.ingestor(),
            be.querier(),
            rosetta_files,
            &domain_config,
            &domain_config.defaults.type_suffix,
        )
        .await?;
        println!("Pass 1b complete: {}", outcome.stats);
        mox_covered.extend(outcome.stats.bridged_titles.iter().cloned());
    }

    // Pass 1a: Ingest JSON schemas (no entity classification). Optional
    // under mox-first: skipped entirely when only .mox files are provided,
    // and titles already created from .mox are skipped within the pass.
    if let Some(schemas_dir) = schemas {
        let empty_entities = HashSet::new();
        let ingest_result = crate::ingest::async_ingest::ingest_schemas_with_skips(
            be.ingestor(),
            schemas_dir,
            &classifier_config,
            &empty_entities,
            &ui_overrides,
            &domain_config.defaults.type_suffix,
            &mox_covered,
        )
        .await?;
        println!(
            "Pass 1a: {} schemas ingested",
            ingest_result.schemas_created
        );
    }

    // Pass 1a (alias wiring): imported-schema aliases resolve now that both
    // the imported files and the --schemas pass have run — exact title
    // match, then title + type suffix; misses warn and skip the edge
    // (issue #230).
    if !pending_alias_refs.is_empty() {
        crate::ingest::mox_ingest::wire_alias_refs(
            be.ingestor(),
            be.querier(),
            &pending_alias_refs,
            &domain_config.defaults.type_suffix,
            &mut mox_stats,
        )
        .await?;
        println!(
            "Pass 1a wiring: {} aliases resolved, {} unresolved",
            mox_stats.resolved_aliases, mox_stats.unresolved_aliases
        );
    }

    // Pass 1b: Ingest IFML DSL files (if provided)
    if !ifml_files.is_empty() {
        println!("Pass 1b: {} IFML files to ingest", ifml_files.len());
        let mut total_stats = crate::ingest::ifml_ingest::IfmlIngestStats::default();
        for ifml_path in ifml_files {
            let model = rex_ifml::parse_ifml_file(ifml_path).map_err(|e| {
                crate::error::Error::Config(format!(
                    "Failed to parse IFML file '{}': {}",
                    ifml_path.display(),
                    e
                ))
            })?;
            let mut stats =
                crate::ingest::ifml_ingest::ingest_ifml_model(be.ingestor(), &model).await?;
            stats.imported_policies = crate::ifml_actor_import::ingest_actor_imports(
                be.ingestor(),
                be.querier(),
                &model,
                ifml_path,
            )
            .await?;
            total_stats.view_containers += stats.view_containers;
            total_stats.containers += stats.containers;
            total_stats.components += stats.components;
            total_stats.events += stats.events;
            total_stats.parameters += stats.parameters;
            total_stats.actions += stats.actions;
            total_stats.module_uses += stats.module_uses;
            total_stats.actors += stats.actors;
            total_stats.imported_policies += stats.imported_policies;
        }
        println!("Pass 1b complete: {total_stats}");
    }

    // Pass 1c: Ingest API model from domain configuration
    {
        let api_stats =
            crate::ingest::api_ingest::ingest_api_model(be.ingestor(), &domain_config).await?;
        println!("Pass 1c complete: {api_stats}");
    }

    // Pass 1d: Ingest OpenAPI spec files (if provided)
    if !openapi_files.is_empty() {
        println!("Pass 1d: {} OpenAPI files to ingest", openapi_files.len());
        for openapi_path in openapi_files {
            let stats =
                crate::ingest::openapi_ingest::ingest_openapi_file(be.ingestor(), openapi_path)
                    .await?;
            println!("  ingested {}: {stats}", openapi_path.display());
        }
    }

    // Auto-classify
    let classifier_types: HashSet<String> = classifier_config
        .primitive_wrappers
        .keys()
        .cloned()
        .chain(classifier_config.array_wrappers.keys().cloned())
        .chain(classifier_config.range_wrappers.keys().cloned())
        .chain(
            classifier_config
                .composite_wrappers
                .iter()
                .map(|cw| cw.schema.clone()),
        )
        .collect();

    let all_data = be
        .querier()
        .get_classification_data()
        .await
        .map_err(crate::error::Error::Graph)?;

    let naming_rules = classifier_config.naming_rules.clone();
    let auto_classifier = crate::classify::AutoClassifier::new(classifier_types, naming_rules);
    let mut entity_names = HashSet::new();

    let mut sorted_domain_names: Vec<&String> = domain_config.domains.keys().collect();
    sorted_domain_names.sort();
    for domain_name in &sorted_domain_names {
        let domain_entry = &domain_config.domains[domain_name.as_str()];
        let domain_schemas: Vec<_> = all_data
            .iter()
            .filter(|d| d.domain.as_deref() == Some(domain_name.as_str()))
            .cloned()
            .collect();
        let result = auto_classifier.classify_domain(domain_name, domain_entry, &domain_schemas);
        for score in &result.entities {
            entity_names.insert(score.title.clone());
        }
    }

    // Also include legacy entities[] for backward compat during migration
    for domain_entry in domain_config.domains.values() {
        for entity in &domain_entry.entities {
            entity_names.insert(entity.clone());
        }
    }

    println!("Auto-classified {} entities", entity_names.len());

    // Pass 2: Update graph with entity flags
    crate::ingest::async_ingest::reclassify_with_entities(
        be.ingestor(),
        be.querier(),
        &entity_names,
    )
    .await?;

    // AT Protocol projection pass — populates Lexicon/Collection/Namespace nodes
    if let Some(ref pc) = project_config {
        if pc.has_atproto {
            crate::ingest::atproto_projection::project_atproto_lexicons(
                be.ingestor(),
                be.querier(),
                &domain_config,
                pc,
            )
            .await
            .map_err(|e| {
                crate::error::Error::Config(format!("AT Protocol projection failed: {e}"))
            })?;
        }
    }

    let override_dirs: Vec<&Path> = template_dir.iter().map(|p| p.as_path()).collect();

    // Precedence: project template dirs > design-system pack templates >
    // embedded built-ins.
    let design_system = effective_design_system(ifml_design_system, build_plan.as_ref());
    let tera =
        crate::generate::template_engine::create_tera_for_run(design_system, &override_dirs)?;

    let ext_config = match extension_points_path {
        Some(path) => Some(
            codegraph_ext_points::parse_extension_points(path)
                .map_err(|e| crate::error::Error::Config(e.to_string()))?,
        ),
        None => None,
    };

    run_validation(be.querier(), &domain_config).await?;

    let ifml_component_mappings = load_ifml_component_mappings(ifml_components, design_system)?;

    let report = crate::generate::run_generators_with_opts(crate::generate::GeneratorOpts {
        db: be.querier(),
        config: &domain_config,
        output_dir: output,
        tera: &tera,
        ui_overrides: &ui_overrides,
        ui_domains: &ui_domains,
        // mox-only runs have no schemas dir; an empty path keeps the UI
        // codelist generator's schema-dir lookups graceful (see `generate`).
        schema_base_dir: schemas.unwrap_or_else(|| Path::new("")),
        seed_config: load_seed_config(config_path).as_deref(),
        domain_types_base: domain_types_base_path.as_deref(),
        hooks_base: None,
        ext_points: ext_config.as_ref(),
        build_plan: build_plan.as_ref(),
        ifml_frameworks: ifml_framework.to_vec(),
        ifml_components: ifml_component_mappings.as_ref(),
        project_config: project_config.as_ref(),
        emdash_plugins: None,
        domain_config_dir: config_path.parent(),
    })
    .await?;

    print!("{}", report.summary());
    if report.has_errors() {
        eprintln!("Generation completed with errors. Some entities were skipped.");
    }

    // Run post-generation scripts from the profile plan.
    if let Some(ref plan) = build_plan {
        if !no_post_gen && !plan.post_gen_scripts.is_empty() {
            println!("\nPost-generation scripts:");
            for (section, scripts) in &plan.post_gen_scripts {
                for cmd in scripts {
                    println!("  [{section}] {cmd}");
                    let status = std::process::Command::new("sh")
                        .arg("-c")
                        .arg(cmd)
                        .status()
                        .map_err(|e| {
                            crate::error::Error::Config(format!(
                                "failed to run post_gen script [{section}] {cmd}: {e}"
                            ))
                        })?;
                    if !status.success() {
                        let code = status.code().unwrap_or(-1);
                        return Err(crate::error::Error::Config(format!(
                            "post_gen script [{section}] {cmd} failed (exit {code})"
                        )));
                    }
                }
            }
        }
    }

    println!("Done.");
    Ok(())
}

/// IFML-only UI generation: ingest IFML DSL files (+ optional schemas) and
/// emit framework routes/navigation for the requested frameworks. No entity,
/// DDL, API, or UI-scaffold generators run, and validation is skipped.
pub async fn ifml_generate(args: IfmlGenerateArgs<'_>) -> Result<()> {
    let IfmlGenerateArgs {
        config_path,
        output,
        ifml_files,
        schemas,
        classifier,
        frameworks,
        profiles_config_path,
        template_dir,
        ifml_components,
        ifml_design_system,
    } = args;

    if ifml_files.is_empty() {
        return Err(crate::error::Error::Config(
            "no IFML files provided: --ifml-files is required".to_string(),
        ));
    }
    if schemas.is_some() && classifier.is_none() {
        return Err(crate::error::Error::Config(
            "--classifier is required when --schemas is provided".to_string(),
        ));
    }

    let backend_config = BackendConfig::default();
    let be = create_backend(&backend_config)
        .await
        .map_err(|e| crate::error::Error::Config(e.to_string()))?;

    let domain_config = codegraph_config::config::parse_domain_config(config_path)
        .map_err(|e| crate::error::Error::Config(e.to_string()))?;

    // Pass 1: ingest + classify schemas when provided (entity resolution
    // enrichment for IFML data bindings). `classifier` is guaranteed Some
    // here by the guard above.
    if let (Some(schemas_dir), Some(classifier_path)) = (schemas, classifier) {
        let classifier_config =
            codegraph_classifier::config::parse_classifier_config(classifier_path)
                .map_err(|e| crate::error::Error::Config(e.to_string()))?;

        let empty_entities = HashSet::new();
        let ui_overrides = load_ui_overrides(config_path)?;
        let ingest_result = crate::ingest::async_ingest::ingest_schemas(
            be.ingestor(),
            schemas_dir,
            &classifier_config,
            &empty_entities,
            &ui_overrides,
            &domain_config.defaults.type_suffix,
        )
        .await?;
        println!(
            "Pass 1 complete: {} schemas ingested",
            ingest_result.schemas_created
        );

        // Auto-classify + Pass 2: reclassify with entity flags.
        let classifier_types: HashSet<String> = classifier_config
            .primitive_wrappers
            .keys()
            .cloned()
            .chain(classifier_config.array_wrappers.keys().cloned())
            .chain(classifier_config.range_wrappers.keys().cloned())
            .chain(
                classifier_config
                    .composite_wrappers
                    .iter()
                    .map(|cw| cw.schema.clone()),
            )
            .collect();
        let all_data = be
            .querier()
            .get_classification_data()
            .await
            .map_err(crate::error::Error::Graph)?;
        let naming_rules = classifier_config.naming_rules.clone();
        let auto_classifier = crate::classify::AutoClassifier::new(classifier_types, naming_rules);
        let mut entity_names = HashSet::new();
        let mut sorted_domain_names: Vec<&String> = domain_config.domains.keys().collect();
        sorted_domain_names.sort();
        for domain_name in &sorted_domain_names {
            let domain_entry = &domain_config.domains[domain_name.as_str()];
            let domain_schemas: Vec<_> = all_data
                .iter()
                .filter(|d| d.domain.as_deref() == Some(domain_name.as_str()))
                .cloned()
                .collect();
            let result =
                auto_classifier.classify_domain(domain_name, domain_entry, &domain_schemas);
            for score in &result.entities {
                entity_names.insert(score.title.clone());
            }
        }
        for domain_entry in domain_config.domains.values() {
            for entity in &domain_entry.entities {
                entity_names.insert(entity.clone());
            }
        }
        println!("Auto-classified {} entities", entity_names.len());
        crate::ingest::async_ingest::reclassify_with_entities(
            be.ingestor(),
            be.querier(),
            &entity_names,
        )
        .await?;
    }

    // Pass 1b: ingest IFML DSL files (parse failures are hard errors).
    println!("Pass 1b: {} IFML files to ingest", ifml_files.len());
    let mut total_stats = crate::ingest::ifml_ingest::IfmlIngestStats::default();
    for ifml_path in ifml_files {
        let model = rex_ifml::parse_ifml_file(ifml_path).map_err(|e| {
            crate::error::Error::Config(format!(
                "Failed to parse IFML file '{}': {}",
                ifml_path.display(),
                e
            ))
        })?;
        let mut stats =
            crate::ingest::ifml_ingest::ingest_ifml_model(be.ingestor(), &model).await?;
        stats.imported_policies = crate::ifml_actor_import::ingest_actor_imports(
            be.ingestor(),
            be.querier(),
            &model,
            ifml_path,
        )
        .await?;
        total_stats.view_containers += stats.view_containers;
        total_stats.containers += stats.containers;
        total_stats.components += stats.components;
        total_stats.events += stats.events;
        total_stats.parameters += stats.parameters;
        total_stats.actions += stats.actions;
        total_stats.module_uses += stats.module_uses;
        total_stats.actors += stats.actors;
        total_stats.imported_policies += stats.imported_policies;
    }
    println!("Pass 1b complete: {total_stats}");

    // Pass 1c: ingest API model from domain configuration.
    {
        let api_stats =
            crate::ingest::api_ingest::ingest_api_model(be.ingestor(), &domain_config).await?;
        println!("Pass 1c complete: {api_stats}");
    }

    let frameworks: Vec<String> = if frameworks.is_empty() {
        vec!["svelte".to_string()]
    } else {
        frameworks.to_vec()
    };

    // Resolve the build plan: either from a provided profiles.toml, or a
    // synthesized minimal IFML-only plan. When a profile resolves but does
    // not declare the per-framework generator names (`ifml_route_{fw}`),
    // `--framework` is authoritative and the plan falls back to ifml_only.
    let registry = crate::profile::CapabilityRegistry::new();
    let mut project_config = crate::generate::ProjectConfig {
        api_version: domain_config.defaults.api_version.clone(),
        types_import_prefix: domain_config.defaults.types_import_prefix.clone(),
        ..crate::generate::ProjectConfig::default()
    };
    let build_plan = if let Some(ref profiles_path) = profiles_config_path {
        if !profiles_path.exists() {
            return Err(crate::error::Error::Config(format!(
                "profiles config not found at {}",
                profiles_path.display()
            )));
        }
        let resolved = crate::profile::load_and_resolve_profile(profiles_path, "default", None)?;
        let plan = crate::profile::BuildPlan::from_profile(&resolved, &registry)?;

        let meta = &resolved.meta;
        project_config.app_name = meta.app_name.clone().unwrap_or(project_config.app_name);
        project_config.domain_types_crate = meta
            .domain_types_crate
            .clone()
            .unwrap_or(project_config.domain_types_crate);
        project_config.hooks_api_crate = meta.hooks_api_crate.clone().unwrap_or_default();
        project_config.api_title = meta.api_title.clone().unwrap_or(project_config.api_title);
        project_config.generator_name = meta
            .generator_name
            .clone()
            .unwrap_or(project_config.generator_name);
        project_config.domain_types_base = meta.domain_types_base.clone().unwrap_or_default();
        project_config.hooks_api_base = meta.hooks_api_base.clone().unwrap_or_default();
        project_config.extensions_base = meta.extensions_base.clone().unwrap_or_default();
        project_config.app_config_base = meta.app_config_base.clone().unwrap_or_default();
        project_config.decision_engine_base = meta.decision_engine_base.clone().unwrap_or_default();
        project_config.codegraph_workflow_base =
            meta.codegraph_workflow_base.clone().unwrap_or_default();
        project_config.type_contracts_base = meta.type_contracts_base.clone().unwrap_or_default();
        project_config.database_target = plan.database_target().to_string();
        project_config.persistence_provider = plan.persistence_provider().to_string();
        project_config.deployment_topology = plan.deployment_topology().to_string();

        println!(
            "Using profile \"{}\" — {} global generators",
            resolved.meta.name,
            plan.global_generators.len(),
        );

        let missing: Vec<&String> = frameworks
            .iter()
            .filter(|fw| !plan.has_global_gen(&format!("ifml_route_{fw}")))
            .collect();
        if missing.is_empty() {
            Some(plan)
        } else {
            eprintln!(
                "Warning: profile \"{}\" does not declare per-framework IFML \
                 generators (ifml_route_{}) — falling back to --framework-driven \
                 IFML-only plan",
                resolved.meta.name,
                missing
                    .iter()
                    .map(|fw| fw.as_str())
                    .collect::<Vec<_>>()
                    .join(", "),
            );
            Some(crate::profile::BuildPlan::ifml_only(&frameworks)?)
        }
    } else {
        Some(crate::profile::BuildPlan::ifml_only(&frameworks)?)
    };

    let override_dirs: Vec<&Path> = template_dir.iter().map(|p| p.as_path()).collect();
    let design_system = effective_design_system(ifml_design_system, build_plan.as_ref());
    let tera =
        crate::generate::template_engine::create_tera_for_run(design_system, &override_dirs)?;

    let ifml_component_mappings = load_ifml_component_mappings(ifml_components, design_system)?;

    let report = crate::generate::run_ifml_generators(
        be.querier(),
        &domain_config,
        output,
        &tera,
        &frameworks,
        build_plan.as_ref(),
        &project_config,
        ifml_component_mappings.as_ref(),
    )
    .await?;

    print!("{}", report.summary());
    if report.has_errors() {
        eprintln!("Generation completed with errors. Some views were skipped.");
    }

    println!("Done.");
    Ok(())
}

/// Generate code from an already-ingested backend (no schema ingestion).
pub async fn generate(
    config_path: &Path,
    output: &Path,
    extension_points_path: Option<&Path>,
    template_dir: &[PathBuf],
    ifml_frameworks: &[String],
    ifml_components: Option<&Path>,
    ifml_design_system: Option<&str>,
) -> Result<()> {
    let config = codegraph_config::config::parse_domain_config(config_path)
        .map_err(|e| crate::error::Error::Config(e.to_string()))?;

    let backend_config = BackendConfig::default();
    let be = create_backend(&backend_config)
        .await
        .map_err(|e| crate::error::Error::Config(e.to_string()))?;

    let ui_overrides = load_ui_overrides(config_path)?;
    let ui_domains = load_ui_domains(config_path)?;

    let dirs: Vec<&Path> = template_dir.iter().map(|p| p.as_path()).collect();
    let tera = crate::generate::template_engine::create_tera_for_run(ifml_design_system, &dirs)?;

    let ext_config = match extension_points_path {
        Some(path) => Some(
            codegraph_ext_points::parse_extension_points(path)
                .map_err(|e| crate::error::Error::Config(e.to_string()))?,
        ),
        None => None,
    };

    let api_resources = be
        .querier()
        .get_api_resources()
        .await
        .map_err(crate::error::Error::Graph)?;
    if api_resources.is_empty() {
        println!("No API model nodes found — auto-seeding from domain configuration...");
        let stats = crate::ingest::api_ingest::ingest_api_model(be.ingestor(), &config).await?;
        println!("Auto-seeded: {stats}");
    }

    // generate uses a pre-populated backend; schema base dir is unknown here.
    // Pass an empty path so UiCodelistGenerator skips gracefully.
    run_validation(be.querier(), &config).await?;
    let ifml_component_mappings =
        load_ifml_component_mappings(ifml_components, ifml_design_system)?;
    let report = crate::generate::run_generators_with_opts(crate::generate::GeneratorOpts {
        db: be.querier(),
        config: &config,
        output_dir: output,
        tera: &tera,
        ui_overrides: &ui_overrides,
        ui_domains: &ui_domains,
        schema_base_dir: Path::new(""),
        seed_config: load_seed_config(config_path).as_deref(),
        domain_types_base: None,
        hooks_base: None,
        ext_points: ext_config.as_ref(),
        build_plan: None,
        ifml_frameworks: ifml_frameworks.to_vec(),
        ifml_components: ifml_component_mappings.as_ref(),
        project_config: None,
        emdash_plugins: None,
        domain_config_dir: config_path.parent(),
    })
    .await?;
    print!("{}", report.summary());
    if report.has_errors() {
        eprintln!("Generation completed with errors. Some entities were skipped.");
    }
    Ok(())
}

/// Classify all schemas and show entity/VO decisions. Mox files, when
/// provided, are ingested first: their schemas bypass the classifier and
/// show up in the report with the `override:source=mox` reason.
/// `schemas` is optional when `mox_files` is provided (mox-first, issue
/// #231); the classifier config is only loaded when `classifier_path` is
/// given (an empty config is used otherwise, mirroring `run`).
pub async fn classify(
    schemas: Option<&Path>,
    classifier_path: Option<&Path>,
    config_path: &Path,
    domain_filter: Option<&str>,
    format: ClassifyFormat,
    mox_files: &[PathBuf],
    rosetta_files: &[PathBuf],
) -> Result<()> {
    if schemas.is_none() && mox_files.is_empty() && rosetta_files.is_empty() {
        return Err(crate::error::Error::Config(
            "no model source: provide --mox-files or --rosetta-files (primary) or --schemas"
                .to_string(),
        ));
    }
    let domain_config = codegraph_config::config::parse_domain_config(config_path)
        .map_err(|e| crate::error::Error::Config(e.to_string()))?;
    let classifier_config = match classifier_path {
        Some(classifier) => codegraph_classifier::config::parse_classifier_config(classifier)
            .map_err(|e| crate::error::Error::Config(e.to_string()))?,
        // An empty TOML document deserializes to the all-defaults config.
        None => codegraph_classifier::config::parse_classifier_config_str("")
            .map_err(|e| crate::error::Error::Config(e.to_string()))?,
    };

    let classifier_types: HashSet<String> = classifier_config
        .primitive_wrappers
        .keys()
        .cloned()
        .chain(classifier_config.array_wrappers.keys().cloned())
        .chain(classifier_config.range_wrappers.keys().cloned())
        .chain(
            classifier_config
                .composite_wrappers
                .iter()
                .map(|cw| cw.schema.clone()),
        )
        .collect();

    let backend_config = BackendConfig::default();
    let be = create_backend(&backend_config)
        .await
        .map_err(|e| crate::error::Error::Config(e.to_string()))?;

    let ui_overrides = load_ui_overrides(config_path)?;

    // Mox-first: mox-authored schemas enter the report as
    // `override:source=mox` and shadow same-titled JSON schemas. Imported
    // schema files ingest through the JSON pipeline and their aliases wire
    // after the schema pass (issue #230) so the report sees the same model
    // the run does.
    let mut mox_covered: HashSet<String> = HashSet::new();
    let mut pending_alias_refs: Vec<crate::ingest::mox_ingest::PendingAliasRef> = Vec::new();
    if !mox_files.is_empty() {
        let outcome = crate::ingest::mox_ingest::ingest_mox_files(
            be.ingestor(),
            be.querier(),
            mox_files,
            &domain_config,
            &domain_config.defaults.type_suffix,
        )
        .await?;
        mox_covered.extend(outcome.stats.bridged_titles.iter().cloned());
        pending_alias_refs = outcome.pending_alias_refs;
        if !outcome.imported_files.is_empty() {
            let imported = crate::ingest::async_ingest::ingest_imported_schemas(
                be.ingestor(),
                &outcome.imported_files,
                &classifier_config,
                &ui_overrides,
                &domain_config.defaults.type_suffix,
            )
            .await?;
            mox_covered.extend(imported.titles);
        }
    }

    // Rosetta bridge (issue #257): bridged titles join the skip-set, and
    // because rosetta provenance rides `origin` (not mox's `source`), the
    // classifier auto-scores them — they appear in the report normally.
    if !rosetta_files.is_empty() {
        let outcome = crate::ingest::rosetta_ingest::ingest_rosetta_files(
            be.ingestor(),
            be.querier(),
            rosetta_files,
            &domain_config,
            &domain_config.defaults.type_suffix,
        )
        .await?;
        mox_covered.extend(outcome.stats.bridged_titles.iter().cloned());
    }

    let empty_entities = HashSet::new();
    if let Some(schemas_dir) = schemas {
        crate::ingest::async_ingest::ingest_schemas_with_skips(
            be.ingestor(),
            schemas_dir,
            &classifier_config,
            &empty_entities,
            &ui_overrides,
            &domain_config.defaults.type_suffix,
            &mox_covered,
        )
        .await?;
    }

    if !pending_alias_refs.is_empty() {
        let mut mox_stats = crate::ingest::mox_ingest::MoxIngestStats::default();
        crate::ingest::mox_ingest::wire_alias_refs(
            be.ingestor(),
            be.querier(),
            &pending_alias_refs,
            &domain_config.defaults.type_suffix,
            &mut mox_stats,
        )
        .await?;
    }

    let all_data = be
        .querier()
        .get_classification_data()
        .await
        .map_err(crate::error::Error::Graph)?;

    let naming_rules = classifier_config.naming_rules.clone();
    let auto_classifier = crate::classify::AutoClassifier::new(classifier_types, naming_rules);
    let mut results = Vec::new();

    let mut sorted_domain_names: Vec<&String> = domain_config.domains.keys().collect();
    sorted_domain_names.sort();
    for domain_name in &sorted_domain_names {
        let domain_entry = &domain_config.domains[domain_name.as_str()];
        let domain_schemas: Vec<_> = all_data
            .iter()
            .filter(|d| d.domain.as_deref() == Some(domain_name.as_str()))
            .cloned()
            .collect();

        let result = auto_classifier.classify_domain(domain_name, domain_entry, &domain_schemas);
        results.push(result);
    }

    results.sort_by(|a, b| a.domain.cmp(&b.domain));

    match format {
        ClassifyFormat::Table => crate::classify::output::format_table(&results, domain_filter),
        ClassifyFormat::Json => crate::classify::output::format_json(&results),
    }

    Ok(())
}

async fn run_validation(
    querier: &dyn codegraph_core::traits::GraphQuerier,
    config: &codegraph_config::DomainConfig,
) -> Result<()> {
    let issues = crate::validate::ValidationPass::run(querier, config).await;
    let errors: Vec<_> = issues
        .iter()
        .filter(|i| matches!(i.severity, crate::validate::Severity::Error))
        .collect();
    if !errors.is_empty() {
        for e in &errors {
            eprintln!("  ERR  {} [{}]: {}", e.entity, e.check, e.message);
        }
        return Err(crate::error::Error::Validation(format!(
            "{} validation errors found",
            errors.len()
        )));
    }
    for w in issues
        .iter()
        .filter(|i| matches!(i.severity, crate::validate::Severity::Warning))
    {
        eprintln!("  WARN {} [{}]: {}", w.entity, w.check, w.message);
    }
    Ok(())
}

fn load_ui_overrides(config_path: &Path) -> Result<codegraph_config::UiOverrideConfig> {
    let parent = config_path.parent().ok_or_else(|| {
        crate::error::Error::Config(format!(
            "Config path '{}' has no parent directory",
            config_path.display()
        ))
    })?;
    let path = parent.join("ui-overrides.toml");
    if path.exists() {
        codegraph_config::parse_ui_overrides_config(&path)
            .map_err(|e| crate::error::Error::Config(e.to_string()))
    } else {
        Ok(codegraph_config::UiOverrideConfig::default())
    }
}

fn load_seed_config(config_path: &Path) -> Option<PathBuf> {
    let path = config_path.parent()?.join("seed.toml");
    if path.exists() {
        Some(path)
    } else {
        None
    }
}

fn load_ui_domains(config_path: &Path) -> Result<codegraph_config::UiDomainConfig> {
    let parent = config_path.parent().ok_or_else(|| {
        crate::error::Error::Config(format!(
            "Config path '{}' has no parent directory",
            config_path.display()
        ))
    })?;
    let path = parent.join("ui-domains.toml");
    if path.exists() {
        codegraph_config::parse_ui_domains_config(&path)
            .map_err(|e| crate::error::Error::Config(e.to_string()))
    } else {
        Ok(codegraph_config::UiDomainConfig::default())
    }
}

/// Return the current Git revision hash, or an empty string if unavailable.
fn current_git_rev() -> String {
    std::process::Command::new("git")
        .args(["rev-parse", "HEAD"])
        .output()
        .ok()
        .and_then(|o| String::from_utf8(o.stdout).ok())
        .map(|s| s.trim().to_string())
        .unwrap_or_default()
}

#[cfg(test)]
mod tests {
    use super::*;
    use codegraph_config::SemanticRole;

    #[test]
    fn schemas_deprecation_notice_has_exact_text() {
        assert_eq!(
            schemas_deprecation_notice(),
            "WARN: --schemas is deprecated as the primary model source. Migrate to .mox files: codegraph migrate --schemas <dir> --output <dir>"
        );
    }

    #[test]
    fn mox_primary_notice_states_mox_wins_and_schemas_fill_gaps() {
        let notice = mox_primary_notice();
        assert!(
            notice.starts_with("INFO: .mox files are the primary model source"),
            "{notice}"
        );
        assert!(notice.contains("--schemas fills gaps"), "{notice}");
    }

    #[test]
    fn design_system_arg_beats_profile_feature() {
        let dir = tempfile::tempdir().unwrap();
        let profiles = dir.path().join("profiles.toml");
        std::fs::write(
            &profiles,
            "[profiles.default.meta]\nname = \"default\"\nversion = \"1.0.0\"\n\
             description = \"test\"\n\n\
             [profiles.default.features]\n\
             ifml_design_system = \"shadcn-svelte\"\n",
        )
        .unwrap();
        let resolved =
            crate::profile::load_and_resolve_profile(&profiles, "default", None).unwrap();
        let registry = crate::profile::CapabilityRegistry::new();
        let plan = crate::profile::BuildPlan::from_profile(&resolved, &registry).unwrap();

        assert_eq!(
            effective_design_system(Some("other"), Some(&plan)),
            Some("other")
        );
        assert_eq!(
            effective_design_system(None, Some(&plan)),
            Some("shadcn-svelte")
        );
    }

    #[test]
    fn design_system_defaults_to_none_without_flag_or_feature() {
        assert_eq!(effective_design_system(None, None), None);
        assert_eq!(effective_design_system(Some(""), None), None);
    }

    #[test]
    fn design_system_pack_loads_and_project_entries_win() {
        let dir = tempfile::tempdir().unwrap();
        let project = dir.path().join("ifml-components.toml");
        std::fs::write(
            &project,
            "[[component]]\nrole = \"collection\"\npath = \"$lib/components/MyTable.svelte\"\n",
        )
        .unwrap();

        let merged = load_ifml_component_mappings(Some(&project), Some("shadcn-svelte"))
            .unwrap()
            .unwrap();
        assert_eq!(
            merged
                .resolve_slot("V", "grid", "list", "table", Some(SemanticRole::Collection))
                .unwrap()
                .path,
            "$lib/components/MyTable.svelte"
        );
        assert_eq!(
            merged
                .resolve_slot(
                    "V",
                    "save",
                    "button",
                    "button",
                    Some(SemanticRole::ActionControl)
                )
                .unwrap()
                .export_name(),
            "Button"
        );
    }

    #[test]
    fn design_system_pack_loads_without_project_file() {
        let pack_only = load_ifml_component_mappings(None, Some("shadcn-svelte"))
            .unwrap()
            .unwrap();
        assert_eq!(
            pack_only
                .resolve_by_role("V", SemanticRole::ModalView)
                .unwrap()
                .export_name(),
            "Dialog"
        );
    }

    #[test]
    fn unknown_design_system_pack_is_an_error() {
        let err = load_ifml_component_mappings(None, Some("material"))
            .expect_err("unknown pack must error");
        assert!(err.to_string().contains("unknown IFML design system pack"));
    }
}
